    GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA statement TO meridian_app;
    ALTER DEFAULT PRIVILEGES IN SCHEMA statement GRANT SELECT, INSERT, UPDATE, DELETE ON TABLES TO meridian_app;
  END IF;
END $$;
